import { strFromU8, unzipSync } from "fflate";

const filenamePattern = /^[a-zA-Z0-9._-]{1,160}\.png$/;

export async function readShopMapBundle(file) {
  if (!file?.name?.endsWith(".cmi-map.zip")) throw new Error("Choose a .cmi-map.zip export from the mod.");
  if (file.size > 34 * 1024 * 1024) throw new Error("The map bundle is larger than 34 MiB.");
  let archive;
  let expandedBytes = 0;
  let entries = 0;
  let archiveIssue = null;
  try { archive = unzipSync(new Uint8Array(await file.arrayBuffer()), { filter: entry => {
    entries += 1;
    expandedBytes += entry.originalSize;
    if (entries > 65 || expandedBytes > 33 * 1024 * 1024) {
      archiveIssue = "The ZIP expands beyond the safe map bundle limit.";
      return false;
    }
    if (entry.name === "manifest.json") {
      if (entry.originalSize > 256 * 1024) archiveIssue = "manifest.json is too large.";
      return !archiveIssue;
    }
    return filenamePattern.test(entry.name) && entry.originalSize <= 2 * 1024 * 1024;
  } }); }
  catch { throw new Error("The selected file is not a readable ZIP bundle."); }
  if (archiveIssue) throw new Error(archiveIssue);
  const manifestBytes = archive["manifest.json"];
  if (!manifestBytes) throw new Error("The bundle is missing manifest.json.");
  let manifest;
  try { manifest = JSON.parse(strFromU8(manifestBytes)); }
  catch { throw new Error("manifest.json is invalid."); }
  if (manifest?.schemaVersion !== 1 || !Array.isArray(manifest.tiles) || !manifest.tiles.length) throw new Error("This map export format is unsupported.");
  if (manifest.tiles.length > 64) throw new Error("The bundle contains more than 64 tiles.");
  const files = new Map();
  const names = new Set();
  let total = 0;
  for (const tile of manifest.tiles) {
    if (!filenamePattern.test(tile.filename || "")) throw new Error(`Invalid tile filename: ${tile.filename || "missing"}`);
    if (names.has(tile.filename)) throw new Error(`Duplicate tile filename: ${tile.filename}`);
    names.add(tile.filename);
    const bytes = archive[tile.filename];
    if (!bytes) throw new Error(`The bundle is missing ${tile.filename}.`);
    if (bytes.byteLength !== tile.bytes) throw new Error(`${tile.filename} has the wrong byte size.`);
    const digest = await crypto.subtle.digest("SHA-256", bytes);
    const checksum = [...new Uint8Array(digest)].map(value => value.toString(16).padStart(2, "0")).join("");
    if (checksum !== String(tile.sha256).toLowerCase()) throw new Error(`${tile.filename} failed checksum validation.`);
    total += bytes.byteLength;
    files.set(tile.filename, bytes);
  }
  if (total > 32 * 1024 * 1024) throw new Error("The uncompressed map imagery is larger than 32 MiB.");
  return { manifest, files };
}
