import { useEffect, useMemo, useState } from "react";
import { Image, Loader2, RotateCcw, Trash2, UploadCloud } from "lucide-react";
import { createShopMapDraft, deleteShopMap, finalizeShopMap, publishShopMap, rollbackShopMap, uploadShopMapTile } from "@/lib/adminClient";
import { readShopMapBundle } from "@/lib/shopMapBundle";

const button = "inline-flex items-center justify-center gap-2 rounded-md px-3 py-2 text-xs font-bold uppercase tracking-wider transition-colors disabled:opacity-40 disabled:pointer-events-none";

function Preview({ bundle }) {
  const surface = useMemo(() => bundle?.manifest?.tiles?.filter(tile => tile.layerKind === "surface") || [], [bundle]);
  const [urls, setUrls] = useState(new Map());
  useEffect(() => {
    const next = new Map();
    for (const tile of surface) {
      const bytes = bundle.files.get(tile.filename);
      if (bytes) next.set(tile.filename, URL.createObjectURL(new Blob([bytes], { type: "image/png" })));
    }
    setUrls(next);
    return () => { for (const url of next.values()) URL.revokeObjectURL(url); };
  }, [bundle, surface]);
  const bounds = bundle?.manifest?.bounds;
  if (!urls.size || !bounds) return null;
  const width = bounds.maxX-bounds.minX;
  const height = bounds.maxZ-bounds.minZ;
  const marker = Math.max(2, Math.min(10, Math.max(width, height)/90));
  const signs = bundle.manifest.capturePlan?.signs || [];
  const warps = bundle.manifest.capturePlan?.warps || [];
  return <div className="overflow-hidden rounded-xl border border-white/10 bg-[#080c10] p-3">
    <svg viewBox={`${bounds.minX} ${bounds.minZ} ${width} ${height}`} role="img" aria-label="Surface map preview with shop signs and warp arrivals" className="mx-auto block max-h-80 w-full rounded bg-black/30" preserveAspectRatio="xMidYMid meet">
      <title>{surface.length} surface tiles, {signs.length} observed signs, {warps.length} warp arrivals</title>
      {surface.map(tile => <image key={tile.filename} href={urls.get(tile.filename)} x={tile.minX} y={tile.minZ} width={tile.maxX-tile.minX} height={tile.maxZ-tile.minZ} preserveAspectRatio="none" style={{ imageRendering: "pixelated" }} />)}
      {signs.map((sign, index) => <circle key={`${sign.signFingerprint || index}:${sign.x}:${sign.z}`} cx={sign.x} cy={sign.z} r={marker*.55} fill="#a5b4fc" stroke="#111827" strokeWidth={marker*.2}><title>{sign.itemName || "Chest shop"} · {sign.seller || "Unknown seller"} · Y {sign.y}</title></circle>)}
      {warps.map(warp => <path key={warp.id || warp.warpName} d={`M ${warp.x} ${warp.z-marker} L ${warp.x+marker} ${warp.z+marker*.8} L ${warp.x-marker} ${warp.z+marker*.8} Z`} fill="#fbbf24" stroke="#111827" strokeWidth={marker*.25}><title>/pw {warp.warpName} · Y {warp.y}</title></path>)}
    </svg>
    <p className="mt-2 text-center font-mono text-[10px] text-zinc-500">Surface mosaic · {surface.length} tile{surface.length===1?"":"s"} · {signs.length} signs · {warps.length} arrivals</p>
  </div>;
}

export default function AdminShopMaps({ data, onChanged }) {
  const [bundle, setBundle] = useState(null);
  const [reading, setReading] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [error, setError] = useState(null);
  const owner = data?.role === "owner";
  const groups = useMemo(() => {
    const versions = data?.versions || [];
    const result = new Map();
    for (const version of versions) {
      const key = `${version.ownerType}:${version.ownerId}`;
      if (!result.has(key)) result.set(key, []);
      result.get(key).push(version);
    }
    return [...result.values()];
  }, [data?.versions]);

  const choose = async event => {
    const file = event.target.files?.[0];
    event.target.value = "";
    if (!file) return;
    setReading(true); setError(null); setBundle(null);
    try { setBundle(await readShopMapBundle(file)); }
    catch (next) { setError(next.message); }
    finally { setReading(false); }
  };

  const upload = async () => {
    if (!bundle || uploading) return;
    setUploading(true); setError(null); setProgress(0);
    try {
      const draft = await createShopMapDraft(bundle.manifest);
      const tiles = bundle.manifest.tiles;
      for (let index = 0; index < tiles.length; index += 1) {
        const tile = tiles[index];
        await uploadShopMapTile(draft.draftId, tile.filename, bundle.files.get(tile.filename));
        setProgress(Math.round(((index + 1) / tiles.length) * 100));
      }
      await finalizeShopMap(draft.draftId);
      setBundle(null);
      await onChanged("Map uploaded as a reviewable draft.");
    } catch (next) { setError(next.message); }
    finally { setUploading(false); }
  };

  const mutate = async (action, success) => {
    setError(null);
    try { await action(); await onChanged(success); }
    catch (next) { setError(next.message); }
  };

  return <section className="space-y-5">
    <div className="rounded-2xl border border-white/10 bg-white/[0.025] p-5">
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div><h2 className="font-heading text-xl font-bold">Publish shop terrain</h2><p className="mt-1 max-w-2xl text-sm text-zinc-400">Upload a bundle created by <code>/cmi shopmap finish</code>. Files are validated locally and again by the Worker before becoming a draft.</p></div>
        {owner && <label className={`${button} cursor-pointer border border-indigo-400/30 bg-indigo-500/10 text-indigo-200 hover:bg-indigo-500/20`}>
          {reading ? <Loader2 className="animate-spin" /> : <UploadCloud />} Select bundle
          <input type="file" accept=".zip,.cmi-map.zip" className="sr-only" onChange={choose} />
        </label>}
      </div>
      {!owner && <p className="mt-4 rounded-lg border border-amber-400/20 bg-amber-400/[0.05] p-3 text-xs text-amber-200">Map publication is restricted to the owner role.</p>}
      {error && <p role="alert" className="mt-4 rounded-lg border border-red-500/30 bg-red-500/10 p-3 text-sm text-red-200">{error}</p>}
      {bundle && <div className="mt-5 grid gap-4 lg:grid-cols-2">
        <div className="space-y-3"><div className="rounded-xl border border-white/10 bg-black/20 p-4">
          <div className="font-heading text-lg font-bold">{bundle.manifest.ownerName}</div>
          <div className="mt-1 font-mono text-[10px] text-zinc-500">{bundle.manifest.ownerType} · {bundle.manifest.tiles.length} tiles · {(bundle.manifest.missingLayers || []).length} missing layers</div>
          <p className="mt-3 text-xs text-zinc-400">Captured {bundle.manifest.capturedAt ? new Date(bundle.manifest.capturedAt).toLocaleString() : "at an unknown time"}</p>
        </div><button disabled={uploading} onClick={upload} className={`${button} w-full bg-emerald-500 text-black hover:bg-emerald-400`}>{uploading ? <Loader2 className="animate-spin" /> : <UploadCloud />} {uploading ? `Uploading ${progress}%` : "Create draft"}</button></div>
        <Preview bundle={bundle} />
      </div>}
    </div>

    {!groups.length && <div className="rounded-xl border border-dashed border-white/10 py-14 text-center"><Image className="mx-auto mb-3 text-zinc-600"/><div className="font-heading font-bold">No maps uploaded yet</div><p className="mt-1 text-xs text-zinc-500">Capture a classified shop warp in game to create the first terrain map.</p></div>}
    {groups.map(history => {
      const current = history.find(version => version.status === "published" && !version.retiredAt);
      return <article key={`${history[0].ownerType}:${history[0].ownerId}`} className="rounded-2xl border border-white/10 bg-white/[0.02] p-5">
        <div className="flex flex-wrap items-start justify-between gap-3"><div><h3 className="font-heading text-lg font-bold">{history[0].ownerName}</h3><p className="mt-1 font-mono text-[10px] text-zinc-500">{history[0].ownerType} · {history[0].dimensionKey}</p></div>
          <span className={`rounded-full border px-2.5 py-1 font-mono text-[9px] uppercase ${current ? current.stale ? "border-amber-400/30 text-amber-300" : "border-emerald-400/30 text-emerald-300" : "border-white/10 text-zinc-500"}`}>{current ? current.stale ? "Recapture recommended" : "Published" : "No publication"}</span></div>
        <div className="mt-4 space-y-2">{history.map(version => <div key={version.id} className="flex flex-wrap items-center justify-between gap-3 rounded-lg border border-white/[0.07] bg-black/20 p-3">
          <div><div className="text-sm text-zinc-200">{version.status}{version.retiredAt ? " · retired" : ""}</div><div className="text-[10px] text-zinc-500">{new Date(version.createdAt).toLocaleString()} · {version.tiles?.length || 0} tiles{version.warningCount ? ` · ${version.warningCount} warnings` : ""}</div></div>
          {owner && <div className="flex gap-2">{version.status === "ready" && <button onClick={() => mutate(() => publishShopMap(version.id), "Map published.")} className={`${button} bg-emerald-500 text-black`}>Publish</button>}
            {version.status === "published" && version.retiredAt && <button onClick={() => mutate(() => rollbackShopMap(version.id), "Map version restored.")} className={`${button} border border-indigo-400/30 text-indigo-200`}><RotateCcw/> Restore</button>}
            {!(version.status === "published" && !version.retiredAt) && <button aria-label="Delete map version" onClick={() => mutate(() => deleteShopMap(version.id), "Map version deleted.")} className={`${button} border border-red-500/20 text-red-300`}><Trash2/></button>}</div>}
        </div>)}</div>
      </article>;
    })}
  </section>;
}
